App.tsx:

```tsx
import React from 'react';
import {AsideHeader, type MenuItem} from '@gravity-ui/navigation';
import {Gear, House, Persons, ShoppingCart} from '@gravity-ui/icons';
import {Text, configure} from '@gravity-ui/uikit';
import {OrdersPage} from './OrdersPage';

configure({lang: 'ru'});

type SectionId = 'home' | 'users' | 'orders' | 'settings';

export function App() {
  const [compact, setCompact] = React.useState(false);
  const [section, setSection] = React.useState<SectionId>('orders');

  const menuItems: MenuItem[] = React.useMemo(() => [
    {id: 'home', title: 'Главная', icon: House, current: section === 'home', onItemClick: () => setSection('home')},
    {id: 'users', title: 'Пользователи', icon: Persons, current: section === 'users', onItemClick: () => setSection('users')},
    {id: 'orders', title: 'Заказы', icon: ShoppingCart, current: section === 'orders', onItemClick: () => setSection('orders')},
    {id: 'settings', title: 'Настройки', icon: Gear, current: section === 'settings', onItemClick: () => setSection('settings')},
  ], [section]);

  return (
    <AsideHeader
      logo={{text: 'Админка'}}
      compact={compact}
      onChangeCompact={setCompact}
      menuItems={menuItems}
      renderContent={() => (section === 'orders' ? <OrdersPage/> : <StubPage .../>)}
    />
  );
}
```

Check LogoProps — `logo={{text: '...'}}`. Check LogoProps type: text?: ReactNode. Fine.

StubPage: centered Flex with Text variant="subheader-1" + hint. 

OrdersPage.tsx:

```tsx
import React from 'react';
import {Label, Text, Flex} from '@gravity-ui/uikit';
import {ColumnReorderingProvider, SelectionCheckbox, Table, useRowSelectionFixedHandler, useTable} from '@gravity-ui/table';
import type {ColumnDef, ExpandedState, RowSelectionState} from '@gravity-ui/table/tanstack';

export type OrderStatus = 'new' | 'processing' | 'shipped' | 'delivered' | 'cancelled';

export interface Order {
  id: string;
  number: string;
  customer: string;
  created: string; // ISO date
  itemsCount: number;
  total: number;
  status: OrderStatus;
}

interface OrderGroup {
  id: string;
  isGroup: true;
  status: OrderStatus;
  items: Order[];
}

type RowData = Order | OrderGroup;
```

Discriminating: OrderGroup has `items: Order[]`. Order doesn't have `items`. `'items' in item` works. But Order has itemsCount. Let me name group field `orders` to be safe: isOrderGroup = (item): item is OrderGroup => 'orders' in item.

Status meta:

```ts
const STATUS_ORDER: OrderStatus[] = ['new','processing','shipped','delivered','cancelled'];
const STATUS_META: Record<OrderStatus, {title: string; theme: ...}> = {
  new: {title: 'Новый', theme: 'info'},
